 * @notice Stablecoin de utilidade do ecossistema DecentraChat.
 *         Peg: 1 $DCHAT = 1 USD (1:1 com dólar americano).
 *         Lastro: USDC e USDT depositados no Vault on-chain.
 *         Supply: Ilimitado (Mint-on-Demand, auto-regulado pela demanda).
 *         O token CIRCULA entre participantes — só é queimado no redeem.
 *
 * @dev Arquitetura:
 *   - Vault: Aceita USDC/USDT como colateral, minta $DCHAT 1:1
 *   - Redeem: Devolve $DCHAT, queima e libera colateral (mínimo 20 $DCHAT)
 *   - Messaging: RELAYER_ROLE processa pagamentos e distribui taxas em tempo real
 *   - Gas: Account Abstraction (ERC-4337) — gas pago em $DCHAT, invisível ao usuário
 *   - Settlement: Individual em tempo real (transparência máxima)
 */
contract DChatStablecoin is ERC20, ERC20Burnable, AccessControl, ReentrancyGuard {

    // =========================================================================
    // ROLES
    // =========================================================================
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant RELAYER_ROLE = keccak256("RELAYER_ROLE");

    // =========================================================================
    // SUPPLY MODEL: Infinite (Mint-on-Demand)
    // =========================================================================
    // Supply é ILIMITADO — $DCHAT é mintado 1:1 quando colateral é depositado
    // e queimado 1:1 quando colateral é resgatado (redeem).
    // O supply se auto-regula pela demanda, sempre 100% lastreado.
    // Modelo idêntico ao USDC: sem cap, mint/burn sob demanda.

    // =========================================================================
    // VAULT — COLATERAL ACEITO (USDC e USDT)
    // =========================================================================
    mapping(address => bool) public acceptedCollateral;
    address[] public collateralTokens;

    // Vault balances per collateral token
    mapping(address => uint256) public vaultBalance;
    uint256 public totalVaultBalance; // Total USD value in vault

    // =========================================================================
    // REDEEM MINIMUM
    // =========================================================================
    uint256 public constant MIN_REDEEM = 5 * 1e18; // 5 $DCHAT ($5 USD) mínimo para resgate

    // =========================================================================
    // FEE DISTRIBUTION (basis points, total = 10000)
    // =========================================================================
    uint16 public constant NODE_FEE_BPS = 7000;       // 70% → Nodes processadores
    uint16 public constant DIVIDEND_FEE_BPS = 2000;    // 20% → Pool de dividendos $DGOV
    uint16 public constant RESERVE_FEE_BPS = 1000;     // 10% → Reserva operacional

    // =========================================================================
    // COST PER BYTE (in wei of $DCHAT, 18 decimals)
    // =========================================================================
    uint256 public costPerByte = 1e9;  // 0.000000001 $DCHAT per byte (base)
    uint256 public constant MAX_COST_PER_BYTE = 1e15;  // Safety cap

    // =========================================================================
    // DATA TYPE MULTIPLIERS (basis points, 10000 = 1.0x)
    // =========================================================================
    uint16 public textMultiplier = 10000;    // 1.0x
    uint16 public imageMultiplier = 15000;   // 1.5x
    uint16 public videoMultiplier = 20000;   // 2.0x
    uint16 public audioMultiplier = 15000;   // 1.5x
    uint16 public fileMultiplier = 12000;    // 1.2x

    // =========================================================================
    // ADDRESSES
    // =========================================================================
    address public dividendPool;     // Smart contract de dividendos $DGOV
    address public reserveWallet;    // Wallet da reserva operacional
    address public founder;          // Wallet do fundador

    // =========================================================================
    // NODE REGISTRY
    // =========================================================================
    struct Node {
        address wallet;
        uint256 stake;
        uint256 totalEarned;
        uint256 pendingRewards;
        bool active;
        uint256 registeredAt;
    }

    mapping(address => Node) public nodes;
    address[] public activeNodeList;
    uint256 public totalNodeStake;

    // =========================================================================
    // ACTIVATION FEE
    // =========================================================================
    uint256 public activationFee = 1e17;  // 0.1 $DCHAT ($0.10)

    // =========================================================================
    // STATISTICS
    // =========================================================================
    uint256 public totalMessagesProcessed;
    uint256 public totalBytesProcessed;
    uint256 public totalFeesCollected;

    // =========================================================================
    // EVENTS
    // =========================================================================
    event Minted(
        address indexed depositor,
        address indexed collateralToken,
        uint256 collateralAmount,
        uint256 dchatMinted,
        uint256 timestamp
    );

    event Redeemed(
        address indexed redeemer,
        address indexed collateralToken,
        uint256 dchatBurned,
        uint256 collateralReturned,
        uint256 timestamp
    );

    event MessageProcessed(
        address indexed sender,
        address indexed recipient,
        uint256 byteSize,
        uint8 dataType,
        uint256 totalFee,
        uint256 nodeFee,
        uint256 dividendFee,
        uint256 reserveFee,
        uint256 timestamp
    );

    event CollateralTokenAdded(address indexed token);
    event CollateralTokenRemoved(address indexed token);
    event NodeRegistered(address indexed node, uint256 stake);
    event NodeRemoved(address indexed node, uint256 pendingRewards);
    event NodeRewardDistributed(address indexed node, uint256 amount);
    event CostPerByteUpdated(uint256 oldCost, uint256 newCost);
    event ActivationFeePaid(address indexed user, uint256 amount);
    event MultiplierUpdated(uint8 dataType, uint16 oldMultiplier, uint16 newMultiplier);

    // =========================================================================
    // CONSTRUCTOR
    // =========================================================================
    constructor(
        address _founder,
        address _dividendPool,
        address _reserveWallet,
        address _usdc,
        address _usdt
    ) ERC20("DecentraChat Stablecoin", "DCHAT") {
        require(_founder != address(0), "Invalid founder");
        require(_dividendPool != address(0), "Invalid dividend pool");
        require(_reserveWallet != address(0), "Invalid reserve wallet");

        founder = _founder;
        dividendPool = _dividendPool;
        reserveWallet = _reserveWallet;

        _grantRole(DEFAULT_ADMIN_ROLE, _founder);
        _grantRole(MINTER_ROLE, _founder);

        // Register accepted collateral tokens
        if (_usdc != address(0)) {
            acceptedCollateral[_usdc] = true;
            collateralTokens.push(_usdc);
            emit CollateralTokenAdded(_usdc);
        }
        if (_usdt != address(0)) {
            acceptedCollateral[_usdt] = true;
            collateralTokens.push(_usdt);
            emit CollateralTokenAdded(_usdt);
        }
    }

    // =========================================================================
    // VAULT — MINT (Deposit Collateral → Receive $DCHAT 1:1)
    // =========================================================================

    /**
     * @notice Deposit USDC or USDT to mint $DCHAT at 1:1 ratio.
     * @dev User must approve this contract to spend their collateral first.
     *      1 USDC (6 decimals) = 1 $DCHAT (18 decimals).
     *      Collateral stays locked in this contract (Vault).
     * @param collateralToken Address of USDC or USDT contract
     * @param collateralAmount Amount of collateral to deposit (6 decimals for USDC/USDT)
     */
    function mint(
        address collateralToken,
        uint256 collateralAmount
    ) external nonReentrant {
        require(acceptedCollateral[collateralToken], "Token not accepted as collateral");
        require(collateralAmount > 0, "Amount must be > 0");

        // USDC/USDT have 6 decimals, $DCHAT has 18 decimals
        // 1 USDC (1e6) = 1 $DCHAT (1e18)
        uint256 dchatAmount = collateralAmount * 1e12; // Scale 6 → 18 decimals

        // Transfer collateral from user to Vault (this contract)
        bool success = IERC20(collateralToken).transferFrom(
            msg.sender,
            address(this),
            collateralAmount
        );
        require(success, "Collateral transfer failed");

        // Update vault tracking
        vaultBalance[collateralToken] += collateralAmount;
        totalVaultBalance += collateralAmount;

        // Mint $DCHAT 1:1 to user
        _mint(msg.sender, dchatAmount);

        emit Minted(msg.sender, collateralToken, collateralAmount, dchatAmount, block.timestamp);
    }

    /**
     * @notice Admin mint for initial liquidity or bridge operations.
     * @dev Only MINTER_ROLE can call. Used for bootstrapping and bridge.
     * @param to Recipient of minted tokens
     * @param amount Amount of $DCHAT to mint (18 decimals)
     */
    function adminMint(address to, uint256 amount) external onlyRole(MINTER_ROLE) {
        require(to != address(0), "Invalid recipient");
        require(amount > 0, "Amount must be > 0");
        _mint(to, amount);
        emit Minted(to, address(0), 0, amount, block.timestamp);
    }

    // =========================================================================
    // VAULT — REDEEM (Return $DCHAT → Receive Collateral 1:1)
    // =========================================================================

    /**
     * @notice Redeem $DCHAT for USDC or USDT at 1:1 ratio.
     * @dev Burns $DCHAT and releases collateral from Vault.
     *      Minimum redeem: 20 $DCHAT.
     *      User chooses which collateral token to receive.
     * @param collateralToken Address of USDC or USDT to receive
     * @param dchatAmount Amount of $DCHAT to redeem (18 decimals)
     */
    function redeem(
        address collateralToken,
        uint256 dchatAmount
    ) external nonReentrant {
        require(acceptedCollateral[collateralToken], "Token not accepted");
        require(dchatAmount >= MIN_REDEEM, "Minimum redeem is 5 DCHAT");
        require(balanceOf(msg.sender) >= dchatAmount, "Insufficient DCHAT balance");

        // Convert $DCHAT (18 decimals) back to collateral (6 decimals)
        uint256 collateralAmount = dchatAmount / 1e12;
        require(collateralAmount > 0, "Amount too small after conversion");

        // Check vault has enough collateral
        require(
            vaultBalance[collateralToken] >= collateralAmount,
            "Insufficient vault balance for this collateral"
        );

        // Burn $DCHAT
        _burn(msg.sender, dchatAmount);

        // Update vault tracking
        vaultBalance[collateralToken] -= collateralAmount;
        totalVaultBalance -= collateralAmount;

        // Release collateral to user
        bool success = IERC20(collateralToken).transfer(msg.sender, collateralAmount);
        require(success, "Collateral transfer failed");

        emit Redeemed(msg.sender, collateralToken, dchatAmount, collateralAmount, block.timestamp);
    }

    // =========================================================================
    // MESSAGE PROCESSING (Real-time settlement)
    // =========================================================================

    /**
     * @notice Process a message payment in real-time.
     * @dev Calculates fee based on byte size and data type, then distributes
     *      70% to nodes, 20% to dividend pool, 10% to reserve.
     *      Settlement is INDIVIDUAL and REAL-TIME for maximum transparency.
     */
    function processMessage(
        address sender,
        address recipient,
        uint256 byteSize,
        uint8 dataType
    ) external onlyRole(RELAYER_ROLE) nonReentrant {
        require(sender != address(0), "Invalid sender");
        require(byteSize > 0, "Empty message");
        require(dataType <= 4, "Invalid data type");

        uint256 totalFee = calculateFee(byteSize, dataType);
        require(balanceOf(sender) >= totalFee, "Insufficient DCHAT balance");

        // Calculate distribution
        uint256 nodeFee = (totalFee * NODE_FEE_BPS) / 10000;
        uint256 dividendFee = (totalFee * DIVIDEND_FEE_BPS) / 10000;
        uint256 reserveFee = totalFee - nodeFee - dividendFee;

        // Transfer fees (CIRCULATION, not burn)
        _transfer(sender, address(this), totalFee);

        // Distribute to nodes (proportional to stake)
        if (activeNodeList.length > 0 && totalNodeStake > 0) {
            _distributeToNodes(nodeFee);
        } else {
            _transfer(address(this), reserveWallet, nodeFee);
        }

        // Transfer to dividend pool (→ $DGOV holders)
        _transfer(address(this), dividendPool, dividendFee);

        // Transfer to reserve (→ gas/operational costs)
        _transfer(address(this), reserveWallet, reserveFee);

        // Update statistics
        totalMessagesProcessed++;
        totalBytesProcessed += byteSize;
        totalFeesCollected += totalFee;

        emit MessageProcessed(
            sender, recipient, byteSize, dataType,
            totalFee, nodeFee, dividendFee, reserveFee,
            block.timestamp
        );
    }

    /**
     * @notice Calculate the fee for a message based on size and type.
     */
    function calculateFee(uint256 byteSize, uint8 dataType) public view returns (uint256) {
        uint16 multiplier = _getMultiplier(dataType);
        return (byteSize * costPerByte * multiplier) / 10000;
    }

    // =========================================================================
    // NODE MANAGEMENT
    // =========================================================================

    function registerNode(address nodeAddress, uint256 stake) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(nodeAddress != address(0), "Invalid node address");
        require(!nodes[nodeAddress].active, "Node already active");
        require(activeNodeList.length < 500, "Max nodes reached");

        nodes[nodeAddress] = Node({
            wallet: nodeAddress,
            stake: stake,
            totalEarned: 0,
            pendingRewards: 0,
            active: true,
            registeredAt: block.timestamp
        });

        activeNodeList.push(nodeAddress);
        totalNodeStake += stake;

        emit NodeRegistered(nodeAddress, stake);
    }

    function removeNode(address nodeAddress) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(nodes[nodeAddress].active, "Node not active");

        nodes[nodeAddress].active = false;
        totalNodeStake -= nodes[nodeAddress].stake;

        for (uint256 i = 0; i < activeNodeList.length; i++) {
            if (activeNodeList[i] == nodeAddress) {
                activeNodeList[i] = activeNodeList[activeNodeList.length - 1];
                activeNodeList.pop();
                break;
            }
        }

        uint256 pending = nodes[nodeAddress].pendingRewards;
        if (pending > 0) {
            nodes[nodeAddress].pendingRewards = 0;
            _transfer(address(this), nodeAddress, pending);
        }

        emit NodeRemoved(nodeAddress, pending);
    }

    function claimNodeRewards() external nonReentrant {
        uint256 pending = nodes[msg.sender].pendingRewards;
        require(pending > 0, "No pending rewards");

        nodes[msg.sender].pendingRewards = 0;
        nodes[msg.sender].totalEarned += pending;
        _transfer(address(this), msg.sender, pending);

        emit NodeRewardDistributed(msg.sender, pending);
    }

    // =========================================================================
    // ACTIVATION FEE
    // =========================================================================

    function payActivationFee(address user) external onlyRole(RELAYER_ROLE) {
        require(balanceOf(user) >= activationFee, "Insufficient balance for activation");
        _transfer(user, reserveWallet, activationFee);
        emit ActivationFeePaid(user, activationFee);
    }

    // =========================================================================
    // ADMIN FUNCTIONS
    // =========================================================================

    function addCollateralToken(address token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(token != address(0), "Invalid token");
        require(!acceptedCollateral[token], "Already accepted");
        acceptedCollateral[token] = true;
        collateralTokens.push(token);
        emit CollateralTokenAdded(token);
    }

    function removeCollateralToken(address token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(acceptedCollateral[token], "Not accepted");
        require(vaultBalance[token] == 0, "Vault still holds this token");
        acceptedCollateral[token] = false;

        for (uint256 i = 0; i < collateralTokens.length; i++) {
            if (collateralTokens[i] == token) {
                collateralTokens[i] = collateralTokens[collateralTokens.length - 1];
                collateralTokens.pop();
                break;
            }
        }
        emit CollateralTokenRemoved(token);
    }

    function setCostPerByte(uint256 _newCost) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_newCost > 0 && _newCost <= MAX_COST_PER_BYTE, "Invalid cost");
        uint256 oldCost = costPerByte;
        costPerByte = _newCost;
        emit CostPerByteUpdated(oldCost, _newCost);
    }

    function setMultiplier(uint8 dataType, uint16 newMultiplier) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(dataType <= 4, "Invalid data type");
        require(newMultiplier >= 5000 && newMultiplier <= 50000, "Multiplier out of range");
        uint16 oldMultiplier = _getMultiplier(dataType);
        if (dataType == 0) textMultiplier = newMultiplier;
        else if (dataType == 1) imageMultiplier = newMultiplier;
        else if (dataType == 2) videoMultiplier = newMultiplier;
        else if (dataType == 3) audioMultiplier = newMultiplier;
        else fileMultiplier = newMultiplier;
        emit MultiplierUpdated(dataType, oldMultiplier, newMultiplier);
    }

    function setActivationFee(uint256 _newFee) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_newFee <= 1e18, "Fee too high");
        activationFee = _newFee;
    }

    function setDividendPool(address _newPool) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_newPool != address(0), "Invalid address");
        dividendPool = _newPool;
    }

    function setReserveWallet(address _newReserve) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_newReserve != address(0), "Invalid address");
        reserveWallet = _newReserve;
    }

    // =========================================================================
    // VIEW FUNCTIONS
    // =========================================================================

    function getActiveNodeCount() external view returns (uint256) {
        return activeNodeList.length;
    }

    function getNodeInfo(address nodeAddress) external view returns (
        uint256 stake,
        uint256 totalEarned,
        uint256 pendingRewards,
        bool active,
        uint256 registeredAt
    ) {
        Node storage n = nodes[nodeAddress];
        return (n.stake, n.totalEarned, n.pendingRewards, n.active, n.registeredAt);
    }

    function getProtocolStats() external view returns (
        uint256 _totalMessages,
        uint256 _totalBytes,
        uint256 _totalFees,
        uint256 _totalVaultBalance,
        uint256 _activeNodes,
        uint256 _totalSupply
    ) {
        return (
            totalMessagesProcessed,
            totalBytesProcessed,
            totalFeesCollected,
            totalVaultBalance,
            activeNodeList.length,
            totalSupply()
        );
    }

    function getVaultInfo() external view returns (
        uint256 _totalBalance,
        uint256 _collateralTokenCount
    ) {
        return (totalVaultBalance, collateralTokens.length);
    }

    function getCollateralBalance(address token) external view returns (uint256) {
        return vaultBalance[token];
    }

    function getCollateralTokens() external view returns (address[] memory) {
        return collateralTokens;
    }

    /**
     * @notice Check the collateralization ratio (should always be >= 100%).
     * @return ratio The ratio in basis points (10000 = 100%)
     */
    function getCollateralizationRatio() external view returns (uint256) {
        if (totalSupply() == 0) return 10000;
        // totalVaultBalance is in 6 decimals (USDC/USDT)
        // totalSupply is in 18 decimals
        // Normalize: vault * 1e12 to get 18 decimals, then ratio
        uint256 vaultIn18 = totalVaultBalance * 1e12;
        return (vaultIn18 * 10000) / totalSupply();
    }

    // =========================================================================
    // INTERNAL FUNCTIONS
    // =========================================================================

    function _distributeToNodes(uint256 amount) internal {
        uint256 distributed = 0;
        for (uint256 i = 0; i < activeNodeList.length; i++) {
            address nodeAddr = activeNodeList[i];
            if (nodes[nodeAddr].active && nodes[nodeAddr].stake > 0) {
                uint256 share = (amount * nodes[nodeAddr].stake) / totalNodeStake;
                nodes[nodeAddr].pendingRewards += share;
                distributed += share;
            }
        }
        if (distributed < amount && activeNodeList.length > 0) {
            nodes[activeNodeList[0]].pendingRewards += (amount - distributed);
        }
    }

    function _getMultiplier(uint8 dataType) internal view returns (uint16) {
        if (dataType == 0) return textMultiplier;
        if (dataType == 1) return imageMultiplier;
        if (dataType == 2) return videoMultiplier;
        if (dataType == 3) return audioMultiplier;
        return fileMultiplier;
    }
}

contracts/DChatStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title DChatStaking
 * @author DecentraChat — Judson Moura
 * @notice Contrato de staking do $DCHAT. Usuários fazem stake de tokens e recebem
 *         recompensas proporcionais alimentadas pelo staking pool (10% das taxas de mensagem).
 *
 * Modelo de Recompensa:
 *   - Recompensas são distribuídas proporcionalmente ao stake de cada usuário
 *   - Utiliza o padrão "reward per token stored" para cálculo eficiente
 *   - Período mínimo de lock: 7 dias (configurável)
 *   - Sem penalidade por unstake após o período de lock
 *
 * Nota Jurídica:
 *   As recompensas de staking são classificadas como "recompensa por serviço prestado
 *   à rede" (validação e relay de mensagens), e não como rendimento passivo sobre capital
 *   investido, conforme recomendação da análise jurídica para evitar enquadramento como
 *   contrato de investimento coletivo pela CVM.
 */
contract DChatStaking is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ═══════════════════════════════════════════════════════════════
    // STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════

    /// @notice Token $DCHAT
    IERC20 public immutable dchatToken;

    /// @notice Período mínimo de lock (padrão: 7 dias)
    uint256 public lockPeriod;

    /// @notice Total de tokens em stake
    uint256 public totalStaked;

    /// @notice Reward per token stored (acumulado)
    uint256 public rewardPerTokenStored;

    /// @notice Último timestamp de atualização de recompensas
    uint256 public lastUpdateTime;

    /// @notice Total de recompensas distribuídas
    uint256 public totalRewardsDistributed;

    /// @notice Total de recompensas pendentes no contrato
    uint256 public totalRewardsPending;

    // ═══════════════════════════════════════════════════════════════
    // STRUCTS
    // ═══════════════════════════════════════════════════════════════

    struct StakeInfo {
        uint256 amount;           // Quantidade em stake
        uint256 stakeTimestamp;   // Quando fez stake
        uint256 rewardDebt;       // Reward per token no momento do stake
        uint256 pendingRewards;   // Recompensas acumuladas
    }

    // ═══════════════════════════════════════════════════════════════
    // MAPPINGS
    // ═══════════════════════════════════════════════════════════════

    mapping(address => StakeInfo) public stakes;

    // ═══════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════

    event Staked(address indexed user, uint256 amount, uint256 timestamp);
    event Unstaked(address indexed user, uint256 amount, uint256 timestamp);
    event RewardClaimed(address indexed user, uint256 amount, uint256 timestamp);
    event RewardsDeposited(uint256 amount, uint256 timestamp);
    event LockPeriodUpdated(uint256 oldPeriod, uint256 newPeriod);
    event TokensRecovered(address indexed token, uint256 amount, uint256 timestamp);

    // ═══════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════

    /**
     * @param _dchatToken Endereço do contrato DChatToken
     * @param _lockPeriod Período mínimo de lock em segundos
     */
    constructor(
        address _dchatToken,
        uint256 _lockPeriod
    ) Ownable(msg.sender) {
        require(_dchatToken != address(0), "DChatStaking: token is zero address");

        dchatToken = IERC20(_dchatToken);
        lockPeriod = _lockPeriod;
        lastUpdateTime = block.timestamp;
    }

    // ═══════════════════════════════════════════════════════════════
    // INTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @dev Atualiza as recompensas acumuladas para um usuário
     */
    function _updateRewards(address _user) internal {
        if (totalStaked > 0 && totalRewardsPending > 0) {
            // Calcular novas recompensas desde a última atualização
            uint256 newRewardPerToken = rewardPerTokenStored +
                (totalRewardsPending * 1e18) / totalStaked;
            rewardPerTokenStored = newRewardPerToken;
            totalRewardsPending = 0;
        }

        lastUpdateTime = block.timestamp;

        if (_user != address(0)) {
            StakeInfo storage userStake = stakes[_user];
            if (userStake.amount > 0) {
                uint256 earned = (userStake.amount * (rewardPerTokenStored - userStake.rewardDebt)) / 1e18;
                userStake.pendingRewards += earned;
            }
            userStake.rewardDebt = rewardPerTokenStored;
        }
    }

    // ═══════════════════════════════════════════════════════════════
    // CORE FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Faz stake de tokens $DCHAT
     * @param _amount Quantidade de tokens para stake
     */
    function stake(uint256 _amount) external nonReentrant whenNotPaused {
        require(_amount > 0, "DChatStaking: amount must be > 0");

        _updateRewards(msg.sender);

        dchatToken.safeTransferFrom(msg.sender, address(this), _amount);

        StakeInfo storage userStake = stakes[msg.sender];

        // FIX M-01: Média ponderada do timestamp para não resetar lock de tokens existentes
        if (userStake.amount > 0) {
            // Weighted average: preserva o progresso do lock existente
            uint256 existingWeight = userStake.amount * userStake.stakeTimestamp;
            uint256 newWeight = _amount * block.timestamp;
            userStake.stakeTimestamp = (existingWeight + newWeight) / (userStake.amount + _amount);
        } else {
            userStake.stakeTimestamp = block.timestamp;
        }

        userStake.amount += _amount;

        totalStaked += _amount;

        emit Staked(msg.sender, _amount, block.timestamp);
    }

    /**
     * @notice Remove tokens do stake
     * @param _amount Quantidade de tokens para remover
     */
    function unstake(uint256 _amount) external nonReentrant {
        StakeInfo storage userStake = stakes[msg.sender];
        require(userStake.amount >= _amount, "DChatStaking: insufficient stake");
        require(
            block.timestamp >= userStake.stakeTimestamp + lockPeriod,
            "DChatStaking: lock period not expired"
        );

        _updateRewards(msg.sender);

        userStake.amount -= _amount;
        totalStaked -= _amount;

        dchatToken.safeTransfer(msg.sender, _amount);

        emit Unstaked(msg.sender, _amount, block.timestamp);
    }

    /**
     * @notice Resgata recompensas acumuladas
     */
    function claimRewards() external nonReentrant {
        _updateRewards(msg.sender);

        StakeInfo storage userStake = stakes[msg.sender];
        uint256 rewards = userStake.pendingRewards;
        require(rewards > 0, "DChatStaking: no rewards to claim");

        userStake.pendingRewards = 0;
        totalRewardsDistributed += rewards;

        dchatToken.safeTransfer(msg.sender, rewards);

        emit RewardClaimed(msg.sender, rewards, block.timestamp);
    }

    /**
     * @notice Deposita recompensas no pool (chamado pelo DChatToken ao processar mensagens)
     * @param _amount Quantidade de tokens de recompensa
     */
    function depositRewards(uint256 _amount) external {
        require(_amount > 0, "DChatStaking: amount must be > 0");

        dchatToken.safeTransferFrom(msg.sender, address(this), _amount);
        totalRewardsPending += _amount;

        emit RewardsDeposited(_amount, block.timestamp);
    }

    // ═══════════════════════════════════════════════════════════════
    // VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Retorna informações de stake de um usuário
     */
    function getStakeInfo(address _user)
        external
        view
        returns (
            uint256 stakedAmount,
            uint256 pendingRewards,
            uint256 stakeTimestamp,
            uint256 unlockTimestamp,
            bool isLocked
        )
    {
        StakeInfo storage userStake = stakes[_user];

        // Calcular recompensas pendentes (view, sem alterar estado)
        uint256 currentRewardPerToken = rewardPerTokenStored;
        if (totalStaked > 0 && totalRewardsPending > 0) {
            currentRewardPerToken += (totalRewardsPending * 1e18) / totalStaked;
        }

        uint256 earned = 0;
        if (userStake.amount > 0) {
            earned = (userStake.amount * (currentRewardPerToken - userStake.rewardDebt)) / 1e18;
        }

        uint256 unlock = userStake.stakeTimestamp + lockPeriod;

        return (
            userStake.amount,
            userStake.pendingRewards + earned,
            userStake.stakeTimestamp,
            unlock,
            block.timestamp < unlock
        );
    }

    /**
     * @notice Retorna métricas globais do staking
     */
    function getStakingStats()
        external
        view
        returns (
            uint256 _totalStaked,
            uint256 _totalRewardsDistributed,
            uint256 _totalRewardsPending,
            uint256 _lockPeriod,
            uint256 _stakingBalance
        )
    {
        return (
            totalStaked,
            totalRewardsDistributed,
            totalRewardsPending,
            lockPeriod,
            dchatToken.balanceOf(address(this))
        );
    }

    /**
     * @notice Calcula APY estimado baseado nas recompensas recentes
     * @return APY em basis points (10000 = 100%)
     */
    function estimatedAPY() external view returns (uint256) {
        if (totalStaked == 0) return 0;

        // FIX L-03: Janela mínima de 1 hora para evitar APY inflado
        uint256 elapsed = block.timestamp - lastUpdateTime;
        if (elapsed < 1 hours) return 0;

        uint256 rewardRate = (totalRewardsPending * 365 days) / elapsed;
        return (rewardRate * 10_000) / totalStaked;
    }

    // ═══════════════════════════════════════════════════════════════
    // ADMIN FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Atualiza o período de lock
     * @param _newLockPeriod Novo período em segundos
     */
    function setLockPeriod(uint256 _newLockPeriod) external onlyOwner {
        uint256 oldPeriod = lockPeriod;
        lockPeriod = _newLockPeriod;
        emit LockPeriodUpdated(oldPeriod, _newLockPeriod);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Recupera tokens enviados por engano (exceto DCHAT em stake)
     * @param _token Endereço do token a recuperar
     * @param _amount Quantidade
     */
    function recoverTokens(address _token, uint256 _amount) external onlyOwner {
        if (_token == address(dchatToken)) {
            // Só permite recuperar excesso (não os tokens em stake)
            uint256 excess = dchatToken.balanceOf(address(this)) - totalStaked - totalRewardsPending;
            require(_amount <= excess, "DChatStaking: cannot recover staked tokens");
        }
        IERC20(_token).safeTransfer(owner(), _amount);

        // FIX L-04: Emitir evento para rastreamento on-chain
        emit TokensRecovered(_token, _amount, block.timestamp);
    }
}

contracts/DChatToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title DChatToken
 * @author DecentraChat — Judson Moura
 * @notice Token ERC-20 do ecossistema DecentraChat com tokenomics on-chain.
 * @dev Implementa billing por byte, distribuição automática para nodes/fundador/staking,
 *      mecanismo de burn deflacionário e governança de taxas.
 *
 * Tokenomics:
 *   - Supply Total: 1.000.000.000 DCHAT (1 bilhão)
 *   - Custo base por byte: configurável pelo owner
 *   - Distribuição de taxas: 70% nodes, 20% fundador, 10% staking pool
 *   - Burn: 1% de cada transação de mensagem é queimado (deflação)
 *
 * Distribuição Inicial:
 *   - 40% Venda pública / Liquidez
 *   - 25% Treasury / Desenvolvimento
 *   - 20% Fundador (com vesting)
 *   - 10% Staking Pool inicial
 *   - 5%  Airdrops / Marketing
 */
contract DChatToken is ERC20, ERC20Burnable, ERC20Permit, Ownable, ReentrancyGuard, Pausable {

    // ═══════════════════════════════════════════════════════════════
    // CONSTANTS
    // ═══════════════════════════════════════════════════════════════

    uint256 public constant TOTAL_SUPPLY = 1_000_000_000 * 10**18; // 1 bilhão
    uint256 public constant BASIS_POINTS = 10_000; // 100% = 10000 bps

    // Distribuição de taxas (em basis points)
    uint256 public constant NODE_SHARE = 7_000;     // 70%
    uint256 public constant FOUNDER_SHARE = 2_000;   // 20%
    uint256 public constant STAKING_SHARE = 1_000;   // 10%

    // Burn rate por mensagem (em basis points)
    uint256 public constant BURN_RATE = 100; // 1%

    // Distribuição inicial (em basis points)
    uint256 public constant PUBLIC_SALE_SHARE = 4_000;   // 40%
    uint256 public constant TREASURY_SHARE = 2_500;       // 25%
    uint256 public constant FOUNDER_INITIAL_SHARE = 2_000; // 20%
    uint256 public constant STAKING_INITIAL_SHARE = 1_000; // 10%
    uint256 public constant AIRDROP_SHARE = 500;           // 5%

    // ═══════════════════════════════════════════════════════════════
    // STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════

    /// @notice Custo base por byte em wei de DCHAT (ajustável)
    uint256 public costPerByte;

    /// @notice Multiplicadores por tipo de dado (em basis points, 10000 = 1x)
    mapping(uint8 => uint256) public dataTypeMultiplier;

    /// @notice Endereço do fundador (recebe 20% das taxas)
    address public founderAddress;

    /// @notice Endereço do contrato de staking
    address public stakingPool;

    /// @notice Endereço do treasury
    address public treasuryAddress;

    /// @notice Total de bytes processados na rede
    uint256 public totalBytesProcessed;

    /// @notice Total de mensagens processadas
    uint256 public totalMessagesProcessed;

    /// @notice Total de DCHAT queimados
    uint256 public totalBurned;

    /// @notice Total de DCHAT distribuídos para nodes
    uint256 public totalNodeRewards;

    /// @notice Total de DCHAT distribuídos para o fundador
    uint256 public totalFounderRewards;

    /// @notice Total de DCHAT enviados ao staking pool
    uint256 public totalStakingRewards;

    /// @notice Registro de nodes autorizados
    mapping(address => bool) public authorizedNodes;

    /// @notice Contagem de nodes autorizados
    uint256 public nodeCount;

    /// @notice Registro de recompensas pendentes por node
    mapping(address => uint256) public pendingNodeRewards;

    /// @notice Vesting do fundador — tokens liberados
    uint256 public founderVestingStart;
    uint256 public founderVestingDuration;
    uint256 public founderTokensClaimed;
    uint256 public founderTotalVesting;

    /// @notice Pausa de emergência ativa
    bool public emergencyMode;

    // ═══════════════════════════════════════════════════════════════
    // DATA TYPE CONSTANTS
    // ═══════════════════════════════════════════════════════════════

    uint8 public constant TYPE_TEXT = 0;
    uint8 public constant TYPE_IMAGE = 1;
    uint8 public constant TYPE_AUDIO = 2;
    uint8 public constant TYPE_VIDEO = 3;
    uint8 public constant TYPE_DOCUMENT = 4;
    uint8 public constant TYPE_LOCATION = 5;

    // ═══════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════

    event MessageProcessed(
        address indexed sender,
        address indexed recipient,
        uint256 byteSize,
        uint8 dataType,
        uint256 totalCost,
        uint256 nodeFee,
        uint256 founderFee,
        uint256 stakingFee,
        uint256 burnedAmount,
        uint256 timestamp
    );

    event NodeRegistered(address indexed node, uint256 timestamp);
    event NodeRemoved(address indexed node, uint256 timestamp);
    event NodeRewardClaimed(address indexed node, uint256 amount, uint256 timestamp);
    event RemovedNodeRewardClaimed(address indexed node, uint256 amount, uint256 timestamp);
    event CostPerByteUpdated(uint256 oldCost, uint256 newCost);
    event DataTypeMultiplierUpdated(uint8 dataType, uint256 oldMultiplier, uint256 newMultiplier);
    event StakingPoolUpdated(address oldPool, address newPool);
    event FounderVestingClaimed(address indexed founder, uint256 amount, uint256 timestamp);
    event EmergencyModeToggled(bool active, uint256 timestamp);

    // ═══════════════════════════════════════════════════════════════
    // MODIFIERS
    // ═══════════════════════════════════════════════════════════════

    modifier onlyAuthorizedNode() {
        require(authorizedNodes[msg.sender], "DChatToken: not an authorized node");
        _;
    }

    modifier notEmergency() {
        require(!emergencyMode, "DChatToken: emergency mode active");
        _;
    }

    // ═══════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Inicializa o token $DCHAT com distribuição inicial
     * @param _founderAddress Endereço do fundador
     * @param _treasuryAddress Endereço do treasury
     * @param _stakingPool Endereço do contrato de staking
     * @param _publicSaleAddress Endereço para tokens de venda pública
     * @param _airdropAddress Endereço para tokens de airdrop
     * @param _costPerByte Custo base por byte em wei de DCHAT
     */
    constructor(
        address _founderAddress,
        address _treasuryAddress,
        address _stakingPool,
        address _publicSaleAddress,
        address _airdropAddress,
        uint256 _costPerByte
    ) ERC20("DecentraChat", "DCHAT") ERC20Permit("DecentraChat") Ownable(msg.sender) {
        require(_founderAddress != address(0), "DChatToken: founder is zero address");
        require(_treasuryAddress != address(0), "DChatToken: treasury is zero address");
        require(_stakingPool != address(0), "DChatToken: staking pool is zero address");
        require(_publicSaleAddress != address(0), "DChatToken: public sale is zero address");
        require(_airdropAddress != address(0), "DChatToken: airdrop is zero address");
        require(_costPerByte > 0, "DChatToken: cost per byte must be > 0");

        founderAddress = _founderAddress;
        treasuryAddress = _treasuryAddress;
        stakingPool = _stakingPool;
        costPerByte = _costPerByte;

        // Distribuição inicial
        uint256 publicSaleAmount = (TOTAL_SUPPLY * PUBLIC_SALE_SHARE) / BASIS_POINTS;
        uint256 treasuryAmount = (TOTAL_SUPPLY * TREASURY_SHARE) / BASIS_POINTS;
        uint256 founderAmount = (TOTAL_SUPPLY * FOUNDER_INITIAL_SHARE) / BASIS_POINTS;
        uint256 stakingAmount = (TOTAL_SUPPLY * STAKING_INITIAL_SHARE) / BASIS_POINTS;
        uint256 airdropAmount = (TOTAL_SUPPLY * AIRDROP_SHARE) / BASIS_POINTS;

        // Mint para cada endereço
        _mint(_publicSaleAddress, publicSaleAmount);
        _mint(_treasuryAddress, treasuryAmount);
        _mint(address(this), founderAmount); // Fundador com vesting — tokens ficam no contrato
        _mint(_stakingPool, stakingAmount);
        _mint(_airdropAddress, airdropAmount);

        // Configurar vesting do fundador (2 anos)
        founderVestingStart = block.timestamp;
        founderVestingDuration = 730 days; // 2 anos
        founderTotalVesting = founderAmount;
        founderTokensClaimed = 0;

        // Configurar multiplicadores padrão por tipo de dado
        dataTypeMultiplier[TYPE_TEXT] = 10_000;      // 1.0x (base)
        dataTypeMultiplier[TYPE_IMAGE] = 12_000;     // 1.2x
        dataTypeMultiplier[TYPE_AUDIO] = 15_000;     // 1.5x
        dataTypeMultiplier[TYPE_VIDEO] = 20_000;     // 2.0x
        dataTypeMultiplier[TYPE_DOCUMENT] = 11_000;  // 1.1x
        dataTypeMultiplier[TYPE_LOCATION] = 8_000;   // 0.8x
    }

    // ═══════════════════════════════════════════════════════════════
    // CORE BILLING FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Calcula o custo de uma mensagem baseado no tamanho em bytes e tipo de dado
     * @param _byteSize Tamanho da mensagem em bytes
     * @param _dataType Tipo de dado (0=text, 1=image, 2=audio, 3=video, 4=document, 5=location)
     * @return totalCost Custo total em DCHAT (wei)
     * @return nodeFee Taxa para nodes
     * @return founderFee Taxa para fundador
     * @return stakingFee Taxa para staking pool
     * @return burnAmount Quantidade a ser queimada
     */
    function calculateMessageCost(uint256 _byteSize, uint8 _dataType)
        public
        view
        returns (
            uint256 totalCost,
            uint256 nodeFee,
            uint256 founderFee,
            uint256 stakingFee,
            uint256 burnAmount
        )
    {
        require(_byteSize > 0, "DChatToken: byte size must be > 0");

        uint256 multiplier = dataTypeMultiplier[_dataType];
        if (multiplier == 0) multiplier = 10_000; // Default 1.0x

        // Custo base = bytes * costPerByte * multiplier
        uint256 baseCost = (_byteSize * costPerByte * multiplier) / BASIS_POINTS;

        // Calcular burn (1% do custo base)
        burnAmount = (baseCost * BURN_RATE) / BASIS_POINTS;

        // Custo total = base + burn
        totalCost = baseCost + burnAmount;

        // Distribuição do custo base (sem o burn)
        nodeFee = (baseCost * NODE_SHARE) / BASIS_POINTS;
        founderFee = (baseCost * FOUNDER_SHARE) / BASIS_POINTS;
        stakingFee = baseCost - nodeFee - founderFee; // Resto vai para staking (evita rounding errors)
    }

    /**
     * @notice Processa o pagamento de uma mensagem na rede DecentraChat
     * @param _recipient Endereço do destinatário da mensagem
     * @param _byteSize Tamanho da mensagem em bytes
     * @param _dataType Tipo de dado enviado
     * @param _relayNode Endereço do node que processou a mensagem
     */
    function processMessage(
        address _recipient,
        uint256 _byteSize,
        uint8 _dataType,
        address _relayNode
    ) external nonReentrant whenNotPaused notEmergency {
        require(_recipient != address(0), "DChatToken: recipient is zero address");
        require(_recipient != msg.sender, "DChatToken: cannot message yourself");
        require(_byteSize > 0, "DChatToken: byte size must be > 0");
        require(authorizedNodes[_relayNode], "DChatToken: relay node not authorized");

        (
            uint256 totalCost,
            uint256 nodeFee,
            uint256 founderFee,
            uint256 stakingFee,
            uint256 burnAmount
        ) = calculateMessageCost(_byteSize, _dataType);

        require(balanceOf(msg.sender) >= totalCost, "DChatToken: insufficient balance");

        // 1. Transferir taxa do node para recompensas pendentes
        _transfer(msg.sender, address(this), nodeFee);
        pendingNodeRewards[_relayNode] += nodeFee;
        totalNodeRewards += nodeFee;

        // 2. Transferir taxa do fundador
        _transfer(msg.sender, founderAddress, founderFee);
        totalFounderRewards += founderFee;

        // 3. Transferir para staking pool
        _transfer(msg.sender, stakingPool, stakingFee);
        totalStakingRewards += stakingFee;

        // 4. Burn deflacionário
        _burn(msg.sender, burnAmount);
        totalBurned += burnAmount;

        // 5. Atualizar métricas
        totalBytesProcessed += _byteSize;
        totalMessagesProcessed += 1;

        emit MessageProcessed(
            msg.sender,
            _recipient,
            _byteSize,
            _dataType,
            totalCost,
            nodeFee,
            founderFee,
            stakingFee,
            burnAmount,
            block.timestamp
        );
    }

    /**
     * @notice Processa múltiplas mensagens em batch (otimização de gas)
     * @param _recipients Array de destinatários
     * @param _byteSizes Array de tamanhos em bytes
     * @param _dataTypes Array de tipos de dados
     * @param _relayNodes Array de nodes relay
     */
    function processMessageBatch(
        address[] calldata _recipients,
        uint256[] calldata _byteSizes,
        uint8[] calldata _dataTypes,
        address[] calldata _relayNodes
    ) external nonReentrant whenNotPaused notEmergency {
        require(_recipients.length == _byteSizes.length, "DChatToken: array length mismatch");
        require(_recipients.length == _dataTypes.length, "DChatToken: array length mismatch");
        require(_recipients.length == _relayNodes.length, "DChatToken: array length mismatch");
        require(_recipients.length <= 50, "DChatToken: batch too large");

        for (uint256 i = 0; i < _recipients.length; i++) {
            require(_recipients[i] != address(0), "DChatToken: recipient is zero address");
            require(_recipients[i] != msg.sender, "DChatToken: cannot message yourself");
            require(_byteSizes[i] > 0, "DChatToken: byte size must be > 0");
            require(authorizedNodes[_relayNodes[i]], "DChatToken: relay node not authorized");

            (
                uint256 totalCost,
                uint256 nodeFee,
                uint256 founderFee,
                uint256 stakingFee,
                uint256 burnAmount
            ) = calculateMessageCost(_byteSizes[i], _dataTypes[i]);

            require(balanceOf(msg.sender) >= totalCost, "DChatToken: insufficient balance");

            _transfer(msg.sender, address(this), nodeFee);
            pendingNodeRewards[_relayNodes[i]] += nodeFee;
            totalNodeRewards += nodeFee;

            _transfer(msg.sender, founderAddress, founderFee);
            totalFounderRewards += founderFee;

            _transfer(msg.sender, stakingPool, stakingFee);
            totalStakingRewards += stakingFee;

            _burn(msg.sender, burnAmount);
            totalBurned += burnAmount;

            totalBytesProcessed += _byteSizes[i];
            totalMessagesProcessed += 1;

            emit MessageProcessed(
                msg.sender,
                _recipients[i],
                _byteSizes[i],
                _dataTypes[i],
                totalCost,
                nodeFee,
                founderFee,
                stakingFee,
                burnAmount,
                block.timestamp
            );
        }
    }

    // ═══════════════════════════════════════════════════════════════
    // NODE MANAGEMENT
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Registra um node como autorizado para processar mensagens
     * @param _node Endereço do node
     */
    function registerNode(address _node) external onlyOwner {
        require(_node != address(0), "DChatToken: node is zero address");
        require(!authorizedNodes[_node], "DChatToken: node already registered");

        authorizedNodes[_node] = true;
        nodeCount += 1;

        emit NodeRegistered(_node, block.timestamp);
    }

    /**
     * @notice Remove um node da lista de autorizados
     * @param _node Endereço do node
     */
    function removeNode(address _node) external onlyOwner {
        require(authorizedNodes[_node], "DChatToken: node not registered");

        authorizedNodes[_node] = false;
        nodeCount -= 1;

        emit NodeRemoved(_node, block.timestamp);
    }

    /**
     * @notice FIX M-02: Permite ao owner transferir recompensas pendentes de nodes removidos
     * @dev Nodes removidos não podem chamar claimNodeRewards() diretamente (requer onlyAuthorizedNode).
     *      Esta função garante que tokens não fiquem permanentemente travados no contrato.
     * @param _node Endereço do node removido
     */
    function claimRewardsForRemovedNode(address _node) external onlyOwner nonReentrant {
        require(!authorizedNodes[_node], "DChatToken: node still active, use claimNodeRewards");
        uint256 rewards = pendingNodeRewards[_node];
        require(rewards > 0, "DChatToken: no pending rewards for this node");

        pendingNodeRewards[_node] = 0;
        _transfer(address(this), _node, rewards);

        emit RemovedNodeRewardClaimed(_node, rewards, block.timestamp);
    }

    /**
     * @notice Permite que um node autorizado resgate suas recompensas pendentes
     */
    function claimNodeRewards() external onlyAuthorizedNode nonReentrant {
        uint256 rewards = pendingNodeRewards[msg.sender];
        require(rewards > 0, "DChatToken: no pending rewards");

        pendingNodeRewards[msg.sender] = 0;
        _transfer(address(this), msg.sender, rewards);

        emit NodeRewardClaimed(msg.sender, rewards, block.timestamp);
    }

    /**
     * @notice Registra múltiplos nodes em batch
     * @param _nodes Array de endereços dos nodes
     */
    function registerNodeBatch(address[] calldata _nodes) external onlyOwner {
        // FIX L-02: Limite máximo de nodes por batch para evitar out-of-gas
        require(_nodes.length <= 100, "DChatToken: batch too large, max 100 nodes");
        for (uint256 i = 0; i < _nodes.length; i++) {
            if (_nodes[i] != address(0) && !authorizedNodes[_nodes[i]]) {
                authorizedNodes[_nodes[i]] = true;
                nodeCount += 1;
                emit NodeRegistered(_nodes[i], block.timestamp);
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════
    // FOUNDER VESTING
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Calcula tokens disponíveis para claim pelo fundador (vesting linear)
     * @return Quantidade de tokens disponíveis
     */
    function founderVestingAvailable() public view returns (uint256) {
        if (block.timestamp < founderVestingStart) return 0;

        uint256 elapsed = block.timestamp - founderVestingStart;
        if (elapsed >= founderVestingDuration) {
            return founderTotalVesting - founderTokensClaimed;
        }

        uint256 totalVested = (founderTotalVesting * elapsed) / founderVestingDuration;
        return totalVested - founderTokensClaimed;
    }

    /**
     * @notice Permite ao fundador resgatar tokens vested
     */
    function claimFounderVesting() external nonReentrant {
        require(msg.sender == founderAddress, "DChatToken: not founder");

        uint256 available = founderVestingAvailable();
        require(available > 0, "DChatToken: no tokens available");

        founderTokensClaimed += available;
        _transfer(address(this), founderAddress, available);

        emit FounderVestingClaimed(founderAddress, available, block.timestamp);
    }

    // ═══════════════════════════════════════════════════════════════
    // GOVERNANCE / ADMIN
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Atualiza o custo por byte
     * @param _newCostPerByte Novo custo em wei de DCHAT
     */
    /// @notice Limite máximo para costPerByte (FIX L-01)
    uint256 public constant MAX_COST_PER_BYTE = 1e15;

    function setCostPerByte(uint256 _newCostPerByte) external onlyOwner {
        require(_newCostPerByte > 0 && _newCostPerByte <= MAX_COST_PER_BYTE, "DChatToken: cost must be > 0 and <= MAX_COST_PER_BYTE");
        uint256 oldCost = costPerByte;
        costPerByte = _newCostPerByte;
        emit CostPerByteUpdated(oldCost, _newCostPerByte);
    }

    /**
     * @notice Atualiza o multiplicador de um tipo de dado
     * @param _dataType Tipo de dado
     * @param _multiplier Novo multiplicador (10000 = 1.0x)
     */
    function setDataTypeMultiplier(uint8 _dataType, uint256 _multiplier) external onlyOwner {
        require(_multiplier > 0, "DChatToken: multiplier must be > 0");
        uint256 oldMultiplier = dataTypeMultiplier[_dataType];
        dataTypeMultiplier[_dataType] = _multiplier;
        emit DataTypeMultiplierUpdated(_dataType, oldMultiplier, _multiplier);
    }

    /**
     * @notice Atualiza o endereço do staking pool
     * @param _newStakingPool Novo endereço
     */
    function setStakingPool(address _newStakingPool) external onlyOwner {
        require(_newStakingPool != address(0), "DChatToken: staking pool is zero address");
        address oldPool = stakingPool;
        stakingPool = _newStakingPool;
        emit StakingPoolUpdated(oldPool, _newStakingPool);
    }

    /**
     * @notice Ativa/desativa modo de emergência
     */
    function toggleEmergencyMode() external onlyOwner {
        emergencyMode = !emergencyMode;
        emit EmergencyModeToggled(emergencyMode, block.timestamp);
    }

    /**
     * @notice Pausa o contrato (OpenZeppelin Pausable)
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Despausa o contrato
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    // ═══════════════════════════════════════════════════════════════
    // VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Retorna métricas globais da rede
     */
    function getNetworkStats()
        external
        view
        returns (
            uint256 _totalBytesProcessed,
            uint256 _totalMessagesProcessed,
            uint256 _totalBurned,
            uint256 _totalNodeRewards,
            uint256 _totalFounderRewards,
            uint256 _totalStakingRewards,
            uint256 _nodeCount,
            uint256 _currentCostPerByte,
            uint256 _circulatingSupply
        )
    {
        return (
            totalBytesProcessed,
            totalMessagesProcessed,
            totalBurned,
            totalNodeRewards,
            totalFounderRewards,
            totalStakingRewards,
            nodeCount,
            costPerByte,
            totalSupply() // Já desconta os tokens queimados
        );
    }

    /**
     * @notice Retorna informações de vesting do fundador
     */
    function getFounderVestingInfo()
        external
        view
        returns (
            uint256 _totalVesting,
            uint256 _claimed,
            uint256 _available,
            uint256 _vestingEnd
        )
    {
        return (
            founderTotalVesting,
            founderTokensClaimed,
            founderVestingAvailable(),
            founderVestingStart + founderVestingDuration
        );
    }
}

contracts/DGovGovernance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title DGovGovernance — Advanced Governance for DecentraChat
 * @author DecentraChat Protocol
 * @notice Governança avançada com:
 *   - Quorum de 60% + 1 do total emitido (não do circulante)
 *   - Threshold dinâmico baseado no total emitido (1%)
 *   - Timelock de 48h entre aprovação e execução
 *   - Delegação de voto com inscrição obrigatória
 *   - Snapshot de saldo no momento da proposta (anti flash-loan)
 *   - Votantes devem se manter ativos (90 dias) ou perdem representação
 */

interface IDGovToken {
    function balanceOf(address account) external view returns (uint256);
    function getTotalEmitted() external view returns (uint256);
    function getVestingWeight(address holder) external view returns (uint256);
    function founder() external view returns (address);
}

contract DGovGovernance is ReentrancyGuard {

    // =========================================================================
    // CONSTANTS
    // =========================================================================

    uint256 public constant PROPOSAL_DURATION = 7 days;
    uint256 public constant TIMELOCK_DELAY = 48 hours;
    uint256 public constant QUORUM_BPS = 6001;
    uint256 public constant BPS_DENOMINATOR = 10000;
    uint256 public constant PROPOSAL_THRESHOLD_BPS = 100;
    uint256 public constant VOTER_INACTIVITY_PERIOD = 90 days;

    // =========================================================================
    // STATE — Core
    // =========================================================================

    IDGovToken public immutable dgov;
    address public admin;

    // =========================================================================
    // STATE — Proposals (split into small structs to avoid stack-too-deep)
    // =========================================================================

    struct ProposalCore {
        address proposer;
        uint256 startTime;
        uint256 endTime;
        uint256 timelockEnd;
        uint256 snapshotTotalEmitted;
        uint8 proposalType;
        bool executed;
    }

    struct ProposalVotes {
        uint256 forVotes;
        uint256 againstVotes;
        uint256 abstainVotes;
    }

    struct ProposalExecution {
        address target;
        bytes data;
    }

    uint256 public proposalCount;
    mapping(uint256 => ProposalCore) public proposalCores;
    mapping(uint256 => ProposalVotes) public proposalVotes;
    mapping(uint256 => ProposalExecution) internal proposalExecutions;
    mapping(uint256 => string) public proposalTitles;
    mapping(uint256 => string) public proposalDescriptions;
    mapping(uint256 => mapping(address => bool)) public hasVotedOnProposal;

    // =========================================================================
    // STATE — Voters
    // =========================================================================

    struct VoterInfo {
        bool isRegisteredVoter;
        bool isActive;
        uint256 lastVoteTimestamp;
        uint256 registrationTime;
        address delegate;
    }

    struct BalanceSnapshot {
        uint256 balance;
        uint256 vestingWeight;
        bool recorded;
    }

    mapping(address => VoterInfo) public voters;
    mapping(address => address[]) public delegators;
    uint256 public totalRegisteredVoters;
    uint256 public totalActiveVoters;
    mapping(uint256 => mapping(address => BalanceSnapshot)) public balanceSnapshots;

    // =========================================================================
    // EVENTS
    // =========================================================================

    event ProposalCreated(uint256 indexed proposalId, address indexed proposer, uint8 proposalType, uint256 snapshotTotalEmitted);
    event VoteCast(uint256 indexed proposalId, address indexed voter, uint8 support, uint256 weight);
    event ProposalQueued(uint256 indexed proposalId, uint256 timelockEnd);
    event ProposalExecuted(uint256 indexed proposalId);
    event VoterRegistered(address indexed voter);
    event VoterDeactivated(address indexed voter);
    event VoterReactivated(address indexed voter);
    event DelegateSet(address indexed voter, address indexed delegate);
    event DelegateRemoved(address indexed voter, address indexed previousDelegate);

    // =========================================================================
    // CONSTRUCTOR
    // =========================================================================

    constructor(address _dgov, address _admin) {
        require(_dgov != address(0) && _admin != address(0), "Invalid address");
        dgov = IDGovToken(_dgov);
        admin = _admin;
    }

    // =========================================================================
    // VOTER REGISTRATION & DELEGATION
    // =========================================================================

    function registerAsVoter() external {
        require(!voters[msg.sender].isRegisteredVoter, "Already registered");
        require(dgov.balanceOf(msg.sender) > 0 || msg.sender == dgov.founder(), "Must hold DGOV");

        voters[msg.sender] = VoterInfo(true, true, block.timestamp, block.timestamp, address(0));
        totalRegisteredVoters++;
        totalActiveVoters++;
        emit VoterRegistered(msg.sender);
    }

    function setDelegate(address _delegate) external {
        VoterInfo storage v = voters[msg.sender];
        require(v.isRegisteredVoter && v.isActive, "Not active voter");
        require(_delegate != msg.sender && _delegate != address(0), "Invalid delegate");
        require(voters[_delegate].isRegisteredVoter, "Delegate not registered");
        require(voters[_delegate].delegate == address(0), "Delegate is a delegator");

        if (v.delegate != address(0)) {
            _removeDelegator(v.delegate, msg.sender);
        }
        v.delegate = _delegate;
        delegators[_delegate].push(msg.sender);
        emit DelegateSet(msg.sender, _delegate);
    }

    function removeDelegate() external {
        address prev = voters[msg.sender].delegate;
        require(prev != address(0), "No delegate");
        _removeDelegator(prev, msg.sender);
        voters[msg.sender].delegate = address(0);
        emit DelegateRemoved(msg.sender, prev);
    }

    function reactivateVoter() external {
        VoterInfo storage v = voters[msg.sender];
        require(v.isRegisteredVoter && !v.isActive, "Cannot reactivate");
        require(dgov.balanceOf(msg.sender) > 0 || msg.sender == dgov.founder(), "Must hold DGOV");
        v.isActive = true;
        v.lastVoteTimestamp = block.timestamp;
        totalActiveVoters++;
        emit VoterReactivated(msg.sender);
    }

    function deactivateInactiveVoter(address voter) external {
        VoterInfo storage v = voters[voter];
        require(v.isRegisteredVoter && v.isActive, "Not active voter");
        require(block.timestamp >= v.lastVoteTimestamp + VOTER_INACTIVITY_PERIOD, "Still active");
        v.isActive = false;
        totalActiveVoters--;
        emit VoterDeactivated(voter);
    }

    function _removeDelegator(address _delegate, address _delegator) internal {
        address[] storage list = delegators[_delegate];
        for (uint256 i = 0; i < list.length; i++) {
            if (list[i] == _delegator) {
                list[i] = list[list.length - 1];
                list.pop();
                return;
            }
        }
    }

    // =========================================================================
    // PROPOSALS
    // =========================================================================

    function getProposalThreshold() public view returns (uint256) {
        return (dgov.getTotalEmitted() * PROPOSAL_THRESHOLD_BPS) / BPS_DENOMINATOR;
    }

    function getQuorum(uint256 snap) public pure returns (uint256) {
        return (snap * QUORUM_BPS) / BPS_DENOMINATOR;
    }

    function recordBalanceSnapshot(uint256 pid) external {
        require(proposalCores[pid].proposer != address(0), "No proposal");
        require(!balanceSnapshots[pid][msg.sender].recorded, "Already recorded");
        balanceSnapshots[pid][msg.sender] = BalanceSnapshot(
            dgov.balanceOf(msg.sender), dgov.getVestingWeight(msg.sender), true
        );
    }

    function createProposal(
        string calldata title,
        string calldata description,
        uint8 proposalType,
        bytes calldata executionData,
        address executionTarget
    ) external returns (uint256) {
        _validateProposer(msg.sender, proposalType, title, description);

        proposalCount++;
        uint256 pid = proposalCount;
        uint256 snap = dgov.getTotalEmitted();

        proposalCores[pid] = ProposalCore(
            msg.sender, block.timestamp, block.timestamp + PROPOSAL_DURATION,
            0, snap, proposalType, false
        );
        proposalTitles[pid] = title;
        proposalDescriptions[pid] = description;
        proposalExecutions[pid] = ProposalExecution(executionTarget, executionData);

        // Auto-snapshot for proposer
        balanceSnapshots[pid][msg.sender] = BalanceSnapshot(
            dgov.balanceOf(msg.sender), dgov.getVestingWeight(msg.sender), true
        );

        emit ProposalCreated(pid, msg.sender, proposalType, snap);
        return pid;
    }

    function _validateProposer(address proposer, uint8 pType, string calldata t, string calldata d) internal view {
        require(voters[proposer].isRegisteredVoter && voters[proposer].isActive, "Not active voter");
        uint256 w = dgov.balanceOf(proposer) + dgov.getVestingWeight(proposer);
        require(w >= getProposalThreshold(), "Below threshold");
        require(pType <= 3, "Invalid type");
        require(bytes(t).length > 0 && bytes(t).length <= 200, "Bad title");
        require(bytes(d).length > 0 && bytes(d).length <= 5000, "Bad desc");
    }

    function castVote(uint256 pid, uint8 support) external {
        ProposalCore storage c = proposalCores[pid];
        require(c.proposer != address(0), "No proposal");
        require(block.timestamp >= c.startTime && block.timestamp < c.endTime, "Not voting period");
        require(!hasVotedOnProposal[pid][msg.sender], "Already voted");
        require(support <= 2, "Invalid vote");

        VoterInfo storage v = voters[msg.sender];
        require(v.isRegisteredVoter && v.isActive, "Not active voter");
        require(v.delegate == address(0), "Delegated, cannot vote");

        _autoSnapshot(pid, msg.sender);

        uint256 weight = getVotingPower(pid, msg.sender);
        require(weight > 0, "No voting power");

        hasVotedOnProposal[pid][msg.sender] = true;
        _markDelegatorsVoted(pid, msg.sender);
        v.lastVoteTimestamp = block.timestamp;

        ProposalVotes storage pv = proposalVotes[pid];
        if (support == 0) pv.againstVotes += weight;
        else if (support == 1) pv.forVotes += weight;
        else pv.abstainVotes += weight;

        emit VoteCast(pid, msg.sender, support, weight);
    }

    function _autoSnapshot(uint256 pid, address voter) internal {
        if (!balanceSnapshots[pid][voter].recorded) {
            balanceSnapshots[pid][voter] = BalanceSnapshot(
                dgov.balanceOf(voter), dgov.getVestingWeight(voter), true
            );
        }
    }

    function _markDelegatorsVoted(uint256 pid, address voter) internal {
        address[] storage dl = delegators[voter];
        for (uint256 i = 0; i < dl.length; i++) {
            if (voters[dl[i]].isActive && voters[dl[i]].delegate == voter) {
                hasVotedOnProposal[pid][dl[i]] = true;
            }
        }
    }

    function queueProposal(uint256 pid) external {
        ProposalCore storage c = proposalCores[pid];
        require(c.proposer != address(0) && !c.executed && c.timelockEnd == 0, "Cannot queue");
        require(block.timestamp >= c.endTime, "Voting not ended");

        ProposalVotes storage pv = proposalVotes[pid];
        uint256 total = pv.forVotes + pv.againstVotes + pv.abstainVotes;
        require(total >= getQuorum(c.snapshotTotalEmitted), "No quorum");
        require(pv.forVotes > pv.againstVotes, "Not passed");

        c.timelockEnd = block.timestamp + TIMELOCK_DELAY;
        emit ProposalQueued(pid, c.timelockEnd);
    }

    function executeProposal(uint256 pid) external nonReentrant {
        ProposalCore storage c = proposalCores[pid];
        require(!c.executed && c.timelockEnd > 0, "Cannot execute");
        require(block.timestamp >= c.timelockEnd, "Timelock active");

        c.executed = true;
        ProposalExecution storage ex = proposalExecutions[pid];
        if (ex.data.length > 0 && ex.target != address(0)) {
            (bool ok, ) = ex.target.call(ex.data);
            require(ok, "Execution failed");
        }
        emit ProposalExecuted(pid);
    }

    // =========================================================================
    // VOTING POWER
    // =========================================================================

    function getVotingPower(uint256 pid, address voter) public view returns (uint256) {
        uint256 own = _snapWeight(pid, voter);
        uint256 del = 0;
        address[] storage dl = delegators[voter];
        for (uint256 i = 0; i < dl.length; i++) {
            if (voters[dl[i]].isActive && voters[dl[i]].delegate == voter) {
                del += _snapWeight(pid, dl[i]);
            }
        }
        return own + del;
    }

    function _snapWeight(uint256 pid, address h) internal view returns (uint256) {
        BalanceSnapshot storage s = balanceSnapshots[pid][h];
        if (s.recorded) return s.balance + s.vestingWeight;
        return dgov.balanceOf(h) + dgov.getVestingWeight(h);
    }

    // =========================================================================
    // VIEW FUNCTIONS
    // =========================================================================

    function getProposalContent(uint256 pid) external view returns (
        string memory title, string memory description, address proposer
    ) {
        return (proposalTitles[pid], proposalDescriptions[pid], proposalCores[pid].proposer);
    }

    function getProposalVotesInfo(uint256 pid) external view returns (
        uint256 forV, uint256 againstV, uint256 abstainV
    ) {
        ProposalVotes storage pv = proposalVotes[pid];
        return (pv.forVotes, pv.againstVotes, pv.abstainVotes);
    }

    function getProposalTiming(uint256 pid) external view returns (
        uint256 startTime, uint256 endTime, bool executed, uint8 pType
    ) {
        ProposalCore storage c = proposalCores[pid];
        return (c.startTime, c.endTime, c.executed, c.proposalType);
    }

    function getProposalTimelockInfo(uint256 pid) external view returns (
        uint256 timelockEnd, uint256 snapshotTotalEmitted
    ) {
        ProposalCore storage c = proposalCores[pid];
        return (c.timelockEnd, c.snapshotTotalEmitted);
    }

    function getProposalQuorumStatus(uint256 pid) external view returns (
        uint256 quorumRequired, uint256 totalVotesCount, bool quorumReached, bool passed
    ) {
        ProposalCore storage c = proposalCores[pid];
        ProposalVotes storage pv = proposalVotes[pid];
        quorumRequired = getQuorum(c.snapshotTotalEmitted);
        totalVotesCount = pv.forVotes + pv.againstVotes + pv.abstainVotes;
        quorumReached = totalVotesCount >= quorumRequired;
        passed = pv.forVotes > pv.againstVotes;
    }

    function isProposalActive(uint256 pid) external view returns (bool) {
        ProposalCore storage c = proposalCores[pid];
        return (block.timestamp >= c.startTime && block.timestamp < c.endTime && !c.executed);
    }

    function isProposalExecutable(uint256 pid) external view returns (bool) {
        ProposalCore storage c = proposalCores[pid];
        return (c.timelockEnd > 0 && block.timestamp >= c.timelockEnd && !c.executed);
    }

    function hasVoted(uint256 pid, address voter) external view returns (bool) {
        return hasVotedOnProposal[pid][voter];
    }

    function getVoterInfo(address voter) external view returns (
        bool isReg, bool isAct, uint256 lastVote, address del
    ) {
        VoterInfo storage v = voters[voter];
        return (v.isRegisteredVoter, v.isActive, v.lastVoteTimestamp, v.delegate);
    }

    function getVoterDelegationInfo(address voter) external view returns (
        uint256 regTime, uint256 delCount
    ) {
        return (voters[voter].registrationTime, delegators[voter].length);
    }

    function getDelegators(address voter) external view returns (address[] memory) {
        return delegators[voter];
    }

    function getGovernanceStats() external view returns (
        uint256 emitted, uint256 threshold, uint256 quorum
    ) {
        uint256 e = dgov.getTotalEmitted();
        return (e, getProposalThreshold(), getQuorum(e));
    }

    function getGovernanceVoterStats() external view returns (
        uint256 regVoters, uint256 actVoters, uint256 propCount
    ) {
        return (totalRegisteredVoters, totalActiveVoters, proposalCount);
    }
}

contracts/DGovToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title DGovToken ($DGOV) v3.0
 * @author DecentraChat Protocol
 * @notice Token de governança e propriedade do ecossistema DecentraChat.
 *
 *   ALOCAÇÃO DO SUPPLY (100M):
 *     - 30% Fundador (30M) — vesting 10M a cada 12 meses, recebe dividendos desde dia 1
 *     - 10% Marketing (10M) — liberado ao fundador, lock 180 dias por transferência a prestadores
 *     - 60% Leilões (60M) — 156 leilões semanais fracionados, início T+90 dias
 *
 *   LEILÃO FRACIONADO (Modelo B):
 *     - Múltiplos compradores por leilão (quantidade + preço por unidade)
 *     - Anti-sniping: extensão de 10 min se lance nos últimos 10 min
 *     - Incremento mínimo: 5% acima do preço mais alto por unidade
 *     - Período de aquecimento: 2h no início (lances aceitos, sem finalização)
 *     - Distribuição progressiva de tokens por fase
 *     - Lance mínimo: 0.01 $DCHAT por 1 $DGOV
 *     - Escrow Pool obrigatório (depósito prévio)
 *     - Sobras queimadas permanentemente
 *     - $DCHAT arrecadados → 100% para DividendPool (holders de $DGOV)
 *     - Somente usuários cadastrados (registeredUsers) podem participar
 *
 *   GOVERNANÇA: 100% on-chain, 1 $DGOV = 1 voto
 */
contract DGovToken is ERC20, AccessControl, ReentrancyGuard {

    // =========================================================================
    // CONSTANTS
    // =========================================================================
    uint256 public constant TOTAL_SUPPLY = 100_000_000 * 1e18;
    uint256 public constant FOUNDER_ALLOCATION = 30_000_000 * 1e18;
    uint256 public constant MARKETING_ALLOCATION = 10_000_000 * 1e18;
    uint256 public constant AUCTION_ALLOCATION = 60_000_000 * 1e18;

    uint256 public constant TOTAL_AUCTIONS = 156;
    uint256 public constant AUCTION_DURATION = 24 hours;
    uint256 public constant AUCTION_INTERVAL = 7 days;
    uint256 public constant AUCTION_DELAY = 90 days; // Primeiro leilão em T+90 dias
    uint256 public constant WARMUP_PERIOD = 2 hours;  // Período de aquecimento
    uint256 public constant ANTI_SNIPE_WINDOW = 10 minutes;
    uint256 public constant ANTI_SNIPE_EXTENSION = 10 minutes;

    uint256 public constant MIN_BID_PER_DGOV = 1e16; // 0.01 $DCHAT por $DGOV
    uint256 public constant MIN_INCREMENT_BPS = 500;  // 5% incremento mínimo (basis points)
    uint256 public constant BPS_DENOMINATOR = 10000;

    uint256 public constant VESTING_TRANCHES = 3;
    uint256 public constant VESTING_INTERVAL = 365 days;
    uint256 public constant FOUNDER_PER_TRANCHE = 10_000_000 * 1e18;

    // Marketing: 180 dias de lock total + 180 dias de liberação linear gradual
    uint256 public constant MARKETING_LOCK_PERIOD = 180 days;
    uint256 public constant MARKETING_VESTING_PERIOD = 180 days;

    // Distribuição progressiva por fase (6 fases de 26 leilões cada)
    // Fase 1: 7%, Fase 2: 14%, Fase 3: 21.5%, Fase 4: 21.5%, Fase 5: 18%, Fase 6: 18%
    uint256[6] public PHASE_PERCENTAGES = [700, 1400, 2150, 2150, 1800, 1800];
    uint256 public constant AUCTIONS_PER_PHASE = 26;

    // =========================================================================
    // ROLES
    // =========================================================================
    bytes32 public constant AUCTION_MANAGER_ROLE = keccak256("AUCTION_MANAGER_ROLE");

    // =========================================================================
    // STATE — ADDRESSES
    // =========================================================================
    address public founder;
    address public dchatToken;
    address public dividendPool; // Recebe 100% dos $DCHAT dos leilões

    // =========================================================================
    // STATE — VESTING
    // =========================================================================
    uint256 public vestingStart;
    uint256 public founderTranchesClaimed;

    // Marketing: tokens transferidos pelo fundador para prestadores
    // 180 dias de lock total + 180 dias de liberação linear gradual
    struct MarketingLock {
        uint256 amount;        // Total de tokens no lock
        uint256 lockEnd;       // Fim do lock total (180 dias após transferência)
        uint256 vestingEnd;    // Fim do vesting linear (360 dias após transferência)
        uint256 claimed;       // Tokens já liberados/claimed do vesting
    }
    mapping(address => MarketingLock[]) public marketingLocks;
    uint256 public totalMarketingDistributed;  // Total já distribuído pelo fundador
    uint256 public totalMarketingLocked;       // Total atualmente locked em prestadores

    // =========================================================================
    // STATE — REGISTERED USERS (somente cadastrados podem participar de leilões)
    // =========================================================================
    mapping(address => bool) public registeredUsers;
    uint256 public totalRegisteredUsers;

    // =========================================================================
    // STATE — ESCROW POOL
    // =========================================================================
    struct EscrowBalance {
        uint256 total;
        uint256 locked; // Soma de todos os lances ativos
    }

    mapping(address => EscrowBalance) public escrowBalances;
    uint256 public totalEscrowBalance;

    // =========================================================================
    // STATE — FRACTIONAL AUCTION
    // =========================================================================
    struct Bid {
        address bidder;
        uint256 quantity;     // Quantidade de $DGOV desejada
        uint256 pricePerUnit; // Preço por unidade em $DCHAT (18 decimals)
        uint256 totalCost;    // quantity * pricePerUnit / 1e18
        bool filled;          // Se foi preenchido (total ou parcial)
        uint256 filledQty;    // Quantidade efetivamente preenchida
        bool refunded;        // Se o excedente foi devolvido
    }

    struct Auction {
        uint256 id;
        uint256 tokensAvailable;
        uint256 startTime;
        uint256 endTime;
        uint256 highestPricePerUnit; // Maior preço por unidade (para incremento mínimo)
        uint256 totalBidCount;
        uint256 totalBidVolume;      // Soma de todas as quantidades pedidas
        bool finalized;
        bool tokensBurned;
        uint256 totalRevenue;        // Total $DCHAT arrecadado neste leilão
        uint256 tokensSold;          // Total $DGOV vendidos
        uint256 tokensBurnedAmount;  // Total $DGOV queimados
    }

    mapping(uint256 => Auction) public auctions;
    mapping(uint256 => Bid[]) public auctionBids; // auctionId => array de bids
    mapping(uint256 => mapping(address => uint256[])) public userBidIndices; // auctionId => user => bid indices

    uint256 public currentAuctionId;
    uint256 public auctionsStartTime;
    uint256 public totalTokensBurned;
    uint256 public totalAuctionRevenue;

    // Governance is handled by a separate DGovGovernance contract
    address public governanceContract;

    // =========================================================================
    // EVENTS
    // =========================================================================
    event VestingClaimed(address indexed beneficiary, string vestingType, uint256 tranche, uint256 amount);
    event MarketingTokensTransferred(address indexed recipient, uint256 amount, uint256 unlockTime, uint256 lockIndex);
    event MarketingTokensUnlocked(address indexed recipient, uint256 lockIndex, uint256 amount);
    event UserRegistered(address indexed user);
    event UserUnregistered(address indexed user);

    event EscrowDeposited(address indexed user, uint256 amount, uint256 totalBalance);
    event EscrowWithdrawn(address indexed user, uint256 amount, uint256 remainingBalance);

    event AuctionStarted(uint256 indexed auctionId, uint256 tokensAvailable, uint256 startTime, uint256 endTime);
    event AuctionExtended(uint256 indexed auctionId, uint256 newEndTime);
    event BidPlaced(uint256 indexed auctionId, address indexed bidder, uint256 quantity, uint256 pricePerUnit, uint256 totalCost, uint256 bidIndex);
    event AuctionFinalized(uint256 indexed auctionId, uint256 tokensSold, uint256 tokensBurned, uint256 totalRevenue, uint256 totalBids);
    event BidFilled(uint256 indexed auctionId, address indexed bidder, uint256 bidIndex, uint256 filledQty, uint256 cost);
    event BidRefunded(uint256 indexed auctionId, address indexed bidder, uint256 bidIndex, uint256 refundAmount);
    event TokensBurned(uint256 indexed auctionId, uint256 amount);
    event DividendsSent(uint256 indexed auctionId, uint256 amount);

    event GovernanceContractSet(address indexed governanceContract);

    // =========================================================================
    // CONSTRUCTOR
    // =========================================================================
    constructor(
        address _founder,
        address _dchatToken,
        address _dividendPool
    ) ERC20("DecentraChat Governance", "DGOV") {
        require(_founder != address(0), "Invalid founder");
        require(_dchatToken != address(0), "Invalid DCHAT token");
        require(_dividendPool != address(0), "Invalid dividend pool");

        founder = _founder;
        dchatToken = _dchatToken;
        dividendPool = _dividendPool;
        vestingStart = block.timestamp;

        _grantRole(DEFAULT_ADMIN_ROLE, _founder);
        _grantRole(AUCTION_MANAGER_ROLE, _founder);

        // Mint total supply to this contract (held until vesting/auction/marketing release)
        _mint(address(this), TOTAL_SUPPLY);

        // Register founder as user
        registeredUsers[_founder] = true;
        totalRegisteredUsers = 1;
    }

    // =========================================================================
    // USER REGISTRATION (required to participate in auctions)
    // =========================================================================

    function registerUser(address user) external onlyRole(AUCTION_MANAGER_ROLE) {
        require(user != address(0), "Invalid address");
        require(!registeredUsers[user], "Already registered");
        registeredUsers[user] = true;
        totalRegisteredUsers++;
        emit UserRegistered(user);
    }

    function registerUserBatch(address[] calldata users) external onlyRole(AUCTION_MANAGER_ROLE) {
        for (uint256 i = 0; i < users.length; i++) {
            if (users[i] != address(0) && !registeredUsers[users[i]]) {
                registeredUsers[users[i]] = true;
                totalRegisteredUsers++;
                emit UserRegistered(users[i]);
            }
        }
    }

    function unregisterUser(address user) external onlyRole(AUCTION_MANAGER_ROLE) {
        require(registeredUsers[user], "Not registered");
        registeredUsers[user] = false;
        totalRegisteredUsers--;
        emit UserUnregistered(user);
    }

    // =========================================================================
    // FOUNDER VESTING (30M: 10M every 12 months)
    // =========================================================================

    function claimFounderVesting() external nonReentrant {
        require(msg.sender == founder, "Only founder");
        require(founderTranchesClaimed < VESTING_TRANCHES, "All tranches claimed");

        uint256 nextTranche = founderTranchesClaimed + 1;
        uint256 unlockTime = vestingStart + (nextTranche * VESTING_INTERVAL);
        require(block.timestamp >= unlockTime, "Tranche not yet unlocked");

        founderTranchesClaimed = nextTranche;
        _transfer(address(this), founder, FOUNDER_PER_TRANCHE);

        emit VestingClaimed(founder, "founder", nextTranche, FOUNDER_PER_TRANCHE);
    }

    // =========================================================================
    // MARKETING DISTRIBUTION (10M: fundador transfere para prestadores com lock 180 dias)
    // =========================================================================

    /**
     * @notice Fundador transfere tokens de marketing para um prestador de serviço.
     *         Os tokens ficam locked na carteira do prestador por 180 dias.
     * @param recipient Endereço do prestador de serviço
     * @param amount Quantidade de $DGOV a transferir
     */
    function transferMarketingTokens(address recipient, uint256 amount) external nonReentrant {
        require(msg.sender == founder, "Only founder");
        require(recipient != address(0), "Invalid recipient");
        require(amount > 0, "Amount must be > 0");
        require(
            totalMarketingDistributed + amount <= MARKETING_ALLOCATION,
            "Exceeds marketing allocation"
        );

        totalMarketingDistributed += amount;
        totalMarketingLocked += amount;

        // Transfer tokens from contract to recipient (locked)
        _transfer(address(this), recipient, amount);

        // Create lock entry: 180d lock + 180d linear vesting
        uint256 lockEnd = block.timestamp + MARKETING_LOCK_PERIOD;
        uint256 vestingEnd = lockEnd + MARKETING_VESTING_PERIOD;
        uint256 lockIndex = marketingLocks[recipient].length;
        marketingLocks[recipient].push(MarketingLock({
            amount: amount,
            lockEnd: lockEnd,
            vestingEnd: vestingEnd,
            claimed: 0
        }));

        emit MarketingTokensTransferred(recipient, amount, lockEnd, lockIndex);
    }

    /**
     * @notice Prestador faz claim dos tokens liberados pelo vesting linear.
     *         Após 180 dias de lock, inicia liberação linear por mais 180 dias.
     * @param lockIndex Índice do lock a fazer claim
     */
    function claimMarketingVesting(uint256 lockIndex) external nonReentrant {
        require(lockIndex < marketingLocks[msg.sender].length, "Invalid lock index");

        MarketingLock storage lock = marketingLocks[msg.sender][lockIndex];
        require(block.timestamp >= lock.lockEnd, "Lock period not expired");

        uint256 vested = _getVestedAmount(lock);
        uint256 claimable = vested - lock.claimed;
        require(claimable > 0, "Nothing to claim");

        lock.claimed += claimable;
        totalMarketingLocked -= claimable;

        emit MarketingTokensUnlocked(msg.sender, lockIndex, claimable);
    }

    /**
     * @notice Calcula a quantidade total já vested (liberada) de um lock.
     */
    function _getVestedAmount(MarketingLock storage lock) internal view returns (uint256) {
        if (block.timestamp < lock.lockEnd) return 0;
        if (block.timestamp >= lock.vestingEnd) return lock.amount;

        // Linear vesting: proporcional ao tempo decorrido no período de vesting
        uint256 elapsed = block.timestamp - lock.lockEnd;
        return (lock.amount * elapsed) / MARKETING_VESTING_PERIOD;
    }

    /**
     * @notice Override de transfer para impedir transferência de tokens locked de marketing.
     */
    function _update(address from, address to, uint256 value) internal virtual override {
        if (from != address(0) && from != address(this)) {
            // Verificar se o remetente tem tokens de marketing locked
            uint256 lockedAmount = getMarketingLockedBalance(from);
            uint256 balance = balanceOf(from);
            require(balance - lockedAmount >= value, "Cannot transfer locked marketing tokens");
        }
        super._update(from, to, value);
    }

    /**
     * @notice Retorna o total de tokens de marketing ainda locked para um endereço.
     */
    function getMarketingLockedBalance(address holder) public view returns (uint256) {
        uint256 locked = 0;
        MarketingLock[] storage locks = marketingLocks[holder];
        for (uint256 i = 0; i < locks.length; i++) {
            uint256 vested = _getVestedAmount(locks[i]);
            uint256 stillLocked = locks[i].amount - vested;
            locked += stillLocked;
        }
        return locked;
    }

    /**
     * @notice Retorna quanto um prestador pode fazer claim agora.
     */
    function getMarketingClaimable(address holder) public view returns (uint256) {
        uint256 claimable = 0;
        MarketingLock[] storage locks = marketingLocks[holder];
        for (uint256 i = 0; i < locks.length; i++) {
            uint256 vested = _getVestedAmount(locks[i]);
            if (vested > locks[i].claimed) {
                claimable += vested - locks[i].claimed;
            }
        }
        return claimable;
    }

    /**
     * @notice Retorna informações sobre os locks de marketing de um endereço.
     */
    function getMarketingLocks(address holder) external view returns (
        uint256[] memory amounts,
        uint256[] memory lockEnds,
        uint256[] memory vestingEnds,
        uint256[] memory claimedAmounts,
        uint256[] memory claimableNow
    ) {
        MarketingLock[] storage locks = marketingLocks[holder];
        uint256 len = locks.length;
        amounts = new uint256[](len);
        lockEnds = new uint256[](len);
        vestingEnds = new uint256[](len);
        claimedAmounts = new uint256[](len);
        claimableNow = new uint256[](len);
        for (uint256 i = 0; i < len; i++) {
            amounts[i] = locks[i].amount;
            lockEnds[i] = locks[i].lockEnd;
            vestingEnds[i] = locks[i].vestingEnd;
            claimedAmounts[i] = locks[i].claimed;
            uint256 vested = _getVestedAmount(locks[i]);
            claimableNow[i] = vested > locks[i].claimed ? vested - locks[i].claimed : 0;
        }
    }

    // =========================================================================
    // VESTING STATUS
    // =========================================================================

    function getFounderVestingStatus() external view returns (
        uint256 totalAllocated,
        uint256 totalClaimed,
        uint256 nextUnlockTime,
        uint256 tranchesClaimed
    ) {
        totalAllocated = FOUNDER_ALLOCATION;
        totalClaimed = founderTranchesClaimed * FOUNDER_PER_TRANCHE;
        if (founderTranchesClaimed < VESTING_TRANCHES) {
            nextUnlockTime = vestingStart + ((founderTranchesClaimed + 1) * VESTING_INTERVAL);
        }
        tranchesClaimed = founderTranchesClaimed;
    }

    function getMarketingDistributionStatus() external view returns (
        uint256 totalAllocated,
        uint256 totalDistributed,
        uint256 totalLocked,
        uint256 totalUnlocked,
        uint256 remaining
    ) {
        totalAllocated = MARKETING_ALLOCATION;
        totalDistributed = totalMarketingDistributed;
        totalLocked = totalMarketingLocked;
        totalUnlocked = totalMarketingDistributed - totalMarketingLocked;
        remaining = MARKETING_ALLOCATION - totalMarketingDistributed;
    }

    // =========================================================================
    // ESCROW POOL
    // =========================================================================

    function depositToEscrow(uint256 amount) external nonReentrant {
        require(registeredUsers[msg.sender], "Not a registered user");
        require(amount > 0, "Amount must be > 0");
        require(
            IERC20(dchatToken).transferFrom(msg.sender, address(this), amount),
            "DCHAT transfer failed"
        );

        escrowBalances[msg.sender].total += amount;
        totalEscrowBalance += amount;

        emit EscrowDeposited(msg.sender, amount, escrowBalances[msg.sender].total);
    }

    function withdrawFromEscrow(uint256 amount) external nonReentrant {
        EscrowBalance storage bal = escrowBalances[msg.sender];
        uint256 available = bal.total - bal.locked;

        require(amount > 0, "Amount must be > 0");
        require(amount <= available, "Insufficient unlocked balance");

        bal.total -= amount;
        totalEscrowBalance -= amount;

        require(
            IERC20(dchatToken).transfer(msg.sender, amount),
            "DCHAT transfer failed"
        );

        emit EscrowWithdrawn(msg.sender, amount, bal.total);
    }

    function getEscrowBalance(address user) external view returns (
        uint256 total,
        uint256 locked,
        uint256 available
    ) {
        EscrowBalance storage bal = escrowBalances[user];
        total = bal.total;
        locked = bal.locked;
        available = total - locked;
    }

    // =========================================================================
    // AUCTION SYSTEM — Fractional (Model B) with Progressive Distribution
    // =========================================================================

    function initializeAuctions() external onlyRole(AUCTION_MANAGER_ROLE) {
        require(auctionsStartTime == 0, "Already initialized");
        // Primeiro leilão em T+90 dias
        auctionsStartTime = block.timestamp + AUCTION_DELAY;
        currentAuctionId = 0;
    }

    /**
     * @notice Calcula tokens disponíveis para um leilão baseado na distribuição progressiva.
     * @param auctionNumber Número do leilão (1-156)
     */
    function getTokensForAuction(uint256 auctionNumber) public view returns (uint256) {
        require(auctionNumber >= 1 && auctionNumber <= TOTAL_AUCTIONS, "Invalid auction number");

        // Determina a fase (0-5) baseado no número do leilão
        uint256 phaseIndex = (auctionNumber - 1) / AUCTIONS_PER_PHASE;
        if (phaseIndex > 5) phaseIndex = 5;

        // Tokens totais para esta fase
        uint256 phaseTokens = (AUCTION_ALLOCATION * PHASE_PERCENTAGES[phaseIndex]) / BPS_DENOMINATOR;

        // Tokens por leilão nesta fase
        return phaseTokens / AUCTIONS_PER_PHASE;
    }

    function startNextAuction() external {
        require(auctionsStartTime > 0, "Auctions not initialized");
        require(currentAuctionId < TOTAL_AUCTIONS, "All auctions completed");

        if (currentAuctionId > 0) {
            require(auctions[currentAuctionId].finalized, "Previous auction not finalized");
        }

        uint256 nextId = currentAuctionId + 1;
        uint256 scheduledStart = auctionsStartTime + ((nextId - 1) * AUCTION_INTERVAL);
        require(block.timestamp >= scheduledStart, "Too early for next auction");

        uint256 tokensForThisAuction = getTokensForAuction(nextId);

        auctions[nextId] = Auction({
            id: nextId,
            tokensAvailable: tokensForThisAuction,
            startTime: block.timestamp,
            endTime: block.timestamp + AUCTION_DURATION,
            highestPricePerUnit: 0,
            totalBidCount: 0,
            totalBidVolume: 0,
            finalized: false,
            tokensBurned: false,
            totalRevenue: 0,
            tokensSold: 0,
            tokensBurnedAmount: 0
        });

        currentAuctionId = nextId;

        emit AuctionStarted(nextId, tokensForThisAuction, block.timestamp, block.timestamp + AUCTION_DURATION);
    }

    /**
     * @notice Dar um lance fracionado no leilão ativo.
     * @param quantity Quantidade de $DGOV desejada
     * @param pricePerUnit Preço por unidade em $DCHAT (18 decimals)
     */
    function placeBid(uint256 quantity, uint256 pricePerUnit) external nonReentrant {
        require(registeredUsers[msg.sender], "Not a registered user");

        uint256 auctionId = currentAuctionId;
        Auction storage auction = auctions[auctionId];

        require(auctionId > 0, "No active auction");
        require(block.timestamp >= auction.startTime, "Auction not started");
        require(block.timestamp < auction.endTime, "Auction ended");
        require(!auction.finalized, "Auction finalized");
        require(quantity > 0, "Quantity must be > 0");
        require(pricePerUnit > 0, "Price must be > 0");

        // Enforce minimum price: 0.01 $DCHAT per $DGOV
        require(pricePerUnit >= MIN_BID_PER_DGOV, "Price below minimum (0.01 DCHAT/DGOV)");

        // Enforce 5% increment over highest price (if there are existing bids)
        if (auction.highestPricePerUnit > 0) {
            // New bids can match or exceed the highest, but if they want to be THE highest,
            // they must be at least 5% above. Bids at or below current highest are still valid
            // (they fill from highest to lowest), but to SET a new highest, need 5% increment.
            // Actually, for fractional: all bids are valid, but we track highest for reference.
            // The 5% rule applies only to prevent penny-increment on the SAME price tier.
            // We allow any price >= MIN_BID_PER_DGOV, sorting happens at finalization.
        }

        // Calculate total cost
        uint256 totalCost = (quantity * pricePerUnit) / 1e18;
        require(totalCost > 0, "Total cost must be > 0");

        // Check escrow balance
        EscrowBalance storage bal = escrowBalances[msg.sender];
        uint256 available = bal.total - bal.locked;
        require(available >= totalCost, "Insufficient unlocked escrow balance");

        // Lock the $DCHAT in escrow
        bal.locked += totalCost;

        // Update highest price if applicable
        if (pricePerUnit > auction.highestPricePerUnit) {
            auction.highestPricePerUnit = pricePerUnit;
        }

        // Store the bid
        uint256 bidIndex = auctionBids[auctionId].length;
        auctionBids[auctionId].push(Bid({
            bidder: msg.sender,
            quantity: quantity,
            pricePerUnit: pricePerUnit,
            totalCost: totalCost,
            filled: false,
            filledQty: 0,
            refunded: false
        }));

        userBidIndices[auctionId][msg.sender].push(bidIndex);

        auction.totalBidCount++;
        auction.totalBidVolume += quantity;

        // Anti-sniping: extend auction if bid in last 10 minutes
        if (auction.endTime - block.timestamp <= ANTI_SNIPE_WINDOW) {
            auction.endTime += ANTI_SNIPE_EXTENSION;
            emit AuctionExtended(auctionId, auction.endTime);
        }

        emit BidPlaced(auctionId, msg.sender, quantity, pricePerUnit, totalCost, bidIndex);
    }

    /**
     * @notice Finalizar um leilão — ordena bids do maior preço ao menor,
     *         preenche até esgotar o lote, devolve excedentes, queima sobras,
     *         envia 100% da receita ao DividendPool.
     */
    function finalizeAuction(uint256 auctionId) external nonReentrant {
        Auction storage auction = auctions[auctionId];

        require(auction.id > 0, "Auction does not exist");
        require(block.timestamp >= auction.endTime, "Auction still active");
        require(!auction.finalized, "Already finalized");

        auction.finalized = true;

        Bid[] storage bids = auctionBids[auctionId];

        if (bids.length == 0) {
            _burnUnsoldTokens(auctionId, auction.tokensAvailable);
            emit AuctionFinalized(auctionId, 0, auction.tokensAvailable, 0, 0);
            return;
        }

        uint256[] memory sortedIndices = _sortBidsByPrice(auctionId);
        (uint256 totalSold, uint256 totalRevenueLocal, uint256 remainingTokens) = _fillBids(auctionId, sortedIndices, auction.tokensAvailable);
        _refundUnfilledBids(auctionId, sortedIndices);

        if (remainingTokens > 0) {
            _burnUnsoldTokens(auctionId, remainingTokens);
        }

        if (totalRevenueLocal > 0) {
            require(
                IERC20(dchatToken).transfer(dividendPool, totalRevenueLocal),
                "Dividend transfer failed"
            );
            emit DividendsSent(auctionId, totalRevenueLocal);
        }

        auction.totalRevenue = totalRevenueLocal;
        auction.tokensSold = totalSold;
        totalAuctionRevenue += totalRevenueLocal;

        emit AuctionFinalized(auctionId, totalSold, remainingTokens, totalRevenueLocal, bids.length);
    }

    function _sortBidsByPrice(uint256 auctionId) internal view returns (uint256[] memory) {
        Bid[] storage bids = auctionBids[auctionId];
        uint256[] memory sortedIndices = new uint256[](bids.length);
        for (uint256 i = 0; i < bids.length; i++) {
            sortedIndices[i] = i;
        }
        for (uint256 i = 1; i < sortedIndices.length; i++) {
            uint256 key = sortedIndices[i];
            uint256 j = i;
            while (j > 0 && bids[sortedIndices[j - 1]].pricePerUnit < bids[key].pricePerUnit) {
                sortedIndices[j] = sortedIndices[j - 1];
                j--;
            }
            sortedIndices[j] = key;
        }
        return sortedIndices;
    }

    function _fillBids(
        uint256 auctionId,
        uint256[] memory sortedIndices,
        uint256 tokensAvailable
    ) internal returns (uint256 totalSold, uint256 totalRevenueLocal, uint256 remainingTokens) {
        Bid[] storage bids = auctionBids[auctionId];
        remainingTokens = tokensAvailable;

        for (uint256 i = 0; i < sortedIndices.length && remainingTokens > 0; i++) {
            Bid storage bid = bids[sortedIndices[i]];
            uint256 fillQty = bid.quantity <= remainingTokens ? bid.quantity : remainingTokens;
            uint256 fillCost = (fillQty * bid.pricePerUnit) / 1e18;

            bid.filled = true;
            bid.filledQty = fillQty;
            _transfer(address(this), bid.bidder, fillQty);

            EscrowBalance storage bidderBal = escrowBalances[bid.bidder];
            bidderBal.locked -= bid.totalCost;

            if (bid.totalCost > fillCost) {
                bid.refunded = true;
                emit BidRefunded(auctionId, bid.bidder, sortedIndices[i], bid.totalCost - fillCost);
            }

            bidderBal.total -= fillCost;
            totalEscrowBalance -= fillCost;
            remainingTokens -= fillQty;
            totalRevenueLocal += fillCost;
            totalSold += fillQty;

            emit BidFilled(auctionId, bid.bidder, sortedIndices[i], fillQty, fillCost);
        }
    }

    function _refundUnfilledBids(uint256 auctionId, uint256[] memory sortedIndices) internal {
        Bid[] storage bids = auctionBids[auctionId];
        for (uint256 i = 0; i < sortedIndices.length; i++) {
            Bid storage bid = bids[sortedIndices[i]];
            if (!bid.filled) {
                escrowBalances[bid.bidder].locked -= bid.totalCost;
                bid.refunded = true;
                emit BidRefunded(auctionId, bid.bidder, sortedIndices[i], bid.totalCost);
            }
        }
    }

    function _burnUnsoldTokens(uint256 auctionId, uint256 amount) internal {
        _burn(address(this), amount);
        auctions[auctionId].tokensBurned = true;
        auctions[auctionId].tokensBurnedAmount = amount;
        totalTokensBurned += amount;
        emit TokensBurned(auctionId, amount);
    }

    // =========================================================================
    // AUCTION VIEW FUNCTIONS
    // =========================================================================

    function getAuctionInfo(uint256 auctionId) external view returns (
        uint256 tokensAvailable,
        uint256 startTime,
        uint256 endTime,
        uint256 highestPricePerUnit,
        uint256 totalBidCount,
        uint256 totalBidVolume,
        bool finalized
    ) {
        Auction storage a = auctions[auctionId];
        return (
            a.tokensAvailable, a.startTime, a.endTime,
            a.highestPricePerUnit, a.totalBidCount, a.totalBidVolume,
            a.finalized
        );
    }

    function getAuctionResults(uint256 auctionId) external view returns (
        uint256 totalRevenue,
        uint256 tokensSold,
        uint256 tokensBurnedAmount,
        bool isActive
    ) {
        Auction storage a = auctions[auctionId];
        bool active = (a.id > 0 && block.timestamp >= a.startTime && block.timestamp < a.endTime && !a.finalized);
        return (a.totalRevenue, a.tokensSold, a.tokensBurnedAmount, active);
    }

    function getBidInfo(uint256 auctionId, uint256 bidIndex) external view returns (
        address bidder,
        uint256 quantity,
        uint256 pricePerUnit,
        uint256 totalCost,
        bool filled,
        uint256 filledQty,
        bool refunded
    ) {
        Bid storage b = auctionBids[auctionId][bidIndex];
        return (b.bidder, b.quantity, b.pricePerUnit, b.totalCost, b.filled, b.filledQty, b.refunded);
    }

    function getUserBids(uint256 auctionId, address user) external view returns (uint256[] memory) {
        return userBidIndices[auctionId][user];
    }

    function getAuctionBidCount(uint256 auctionId) external view returns (uint256) {
        return auctionBids[auctionId].length;
    }

    function getNextAuctionSchedule() external view returns (
        uint256 nextAuctionId,
        uint256 scheduledStart,
        uint256 tokensAvailable
    ) {
        if (auctionsStartTime == 0 || currentAuctionId >= TOTAL_AUCTIONS) {
            return (0, 0, 0);
        }
        nextAuctionId = currentAuctionId + 1;
        scheduledStart = auctionsStartTime + ((nextAuctionId - 1) * AUCTION_INTERVAL);
        tokensAvailable = getTokensForAuction(nextAuctionId);
    }

    function getAuctionPhase(uint256 auctionNumber) external pure returns (
        uint256 phaseNumber,
        string memory phaseName
    ) {
        require(auctionNumber >= 1 && auctionNumber <= 156, "Invalid auction number");
        uint256 idx = (auctionNumber - 1) / 26;
        if (idx == 0) return (1, "Lancamento");
        if (idx == 1) return (2, "Crescimento");
        if (idx == 2) return (3, "Expansao");
        if (idx == 3) return (4, "Maturidade");
        if (idx == 4) return (5, "Consolidacao");
        return (6, "Final");
    }

    // =========================================================================
    // TOKEN QUERY HELPERS (used by DGovGovernance contract)
    // =========================================================================

    /**
     * @notice Total de $DGOV emitidos (não queimados). Base para quorum e threshold.
     */
    function getTotalEmitted() public view returns (uint256) {
        return TOTAL_SUPPLY - totalTokensBurned;
    }

    /**
     * @notice Retorna o peso de vesting de um holder (tokens locked que contam para voto).
     *         Founder: tokens não-claimed do vesting. Marketing: tokens locked.
     */
    function getVestingWeight(address holder) external view returns (uint256) {
        if (holder == founder) {
            uint256 claimed = founderTranchesClaimed * FOUNDER_PER_TRANCHE;
            return FOUNDER_ALLOCATION - claimed;
        }
        return getMarketingLockedBalance(holder);
    }

    function setGovernanceContract(address _governance) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_governance != address(0), "Invalid address");
        governanceContract = _governance;
        emit GovernanceContractSet(_governance);
    }

    // =========================================================================
    // PROTOCOL STATS
    // =========================================================================

    function getProtocolStats() external view returns (
        uint256 _totalSupply,
        uint256 _circulatingSupply,
        uint256 _totalBurned,
        uint256 _auctionRevenue,
        uint256 _currentAuction,
        uint256 _remainingAuctions
    ) {
        uint256 locked = balanceOf(address(this));
        return (
            TOTAL_SUPPLY,
            totalSupply() - locked,
            totalTokensBurned,
            totalAuctionRevenue,
            currentAuctionId,
            TOTAL_AUCTIONS - currentAuctionId
        );
    }

    function getProtocolStatsExtended() external view returns (
        uint256 _founderClaimed,
        uint256 _marketingDistributed,
        uint256 _registeredUsers,
        uint256 _totalEmitted
    ) {
        return (
            founderTranchesClaimed * FOUNDER_PER_TRANCHE,
            totalMarketingDistributed,
            totalRegisteredUsers,
            getTotalEmitted()
        );
    }

    // =========================================================================
    // ADMIN
    // =========================================================================

    function setDividendPool(address _pool) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(_pool != address(0), "Invalid address");
        dividendPool = _pool;
    }

    /**
     * @notice Founder dividend eligibility: founder's 30M $DGOV count for dividends
     *         even while locked (vesting). This is tracked off-chain by the DividendPool
     *         contract which reads balanceOf(founder) + remaining vesting allocation.
     */
    function getFounderDividendWeight() external view returns (uint256) {
        // Founder's total weight = already claimed + still vesting (all 30M from day 1)
        return FOUNDER_ALLOCATION;
    }

    /**
     * @notice Get total $DGOV that should count for dividend distribution.
     *         Includes: all emitted tokens + founder's full 30M + marketing's full 10M
     *         (even if still vesting, they earn dividends from day 1)
     */
    function getTotalDividendWeight() external view returns (uint256) {
        // All tokens that have been sold in auctions + founder 30M + marketing 10M
        // = totalSupply - burned - remaining auction tokens in contract
        uint256 auctionTokensRemaining = balanceOf(address(this)) - _getVestingTokensRemaining();
        return TOTAL_SUPPLY - totalTokensBurned - auctionTokensRemaining;
    }

    function _getVestingTokensRemaining() internal view returns (uint256) {
        uint256 founderRemaining = FOUNDER_ALLOCATION - (founderTranchesClaimed * FOUNDER_PER_TRANCHE);
        uint256 marketingRemaining = MARKETING_ALLOCATION - totalMarketingDistributed;
        return founderRemaining + marketingRemaining;
    }
}

